  'results.pdeltaUnstable': "Không có cân bằng bậc hai (kết cấu mất ổn định trước khi đạt tải trọng), nên không có nội lực: {names}.",
  'shellFaces.title': "Mặt, tiêu chuẩn và lực cắt ngang (kN/m², kN/m)",
  'shellFaces.type': "Loại",
  'shellFaces.topVm': "σvM mặt trên",
  'shellFaces.bottomVm': "σvM mặt dưới",
  'shellFaces.topTresca': "Tresca mặt trên",
  'shellFaces.bottomTresca': "Tresca mặt dưới",
  'shellFaces.plate': "Tam giác",
  'shellFaces.quad': "Tứ giác",
  'shellFaces.note': "Mặt: màng ± 6M/t², mặt trên tại z = +t/2 theo z cục bộ. qx và qy: chỉ với phần tử tứ giác MITC4. CSV và Excel có đủ mọi cột, cục bộ và tổng thể. Mô men uốn và ứng suất mặt của vỏ cong không có; dấu gạch hoặc ô trống không có nghĩa là bằng không.",
  'wb.cover.project': "Dự án",
  'wb.cover.client': "Khách hàng",
  'wb.cover.job': "Công việc",
  'wb.cover.jobNumber': "Mã công việc",
  'wb.cover.site': "Công trường",
  'wb.cover.revision': "Phiên bản sửa đổi",
