  'detailing.assembly.level': "Cao độ +{level} m",
  'codes.cirsoc201.anchorage.development': "ld = fy·ψt·ψe·ψg / ({coefficient}·λ·√f′c) · db = {ld} mm cho Ø{db} ({row}, Bảng 25.4.2.3).",
  'codes.cirsoc201.anchorage.developmentMinimum': "ld được tính là {computed} mm cho Ø{db} ({row}, Bảng 25.4.2.3), nâng lên mức tối thiểu {minimum} mm theo §25.4.2.1(b).",
  'codes.cirsoc201.anchorage.rowFavourable': "khoảng hở và lớp bảo vệ thỏa mãn hàng đầu tiên",
  'codes.cirsoc201.anchorage.rowOther': "hàng các trường hợp khác",
  'codes.cirsoc201.anchorage.lap': "Nối chồng loại {spliceClass} = {factor} × ld({ld} mm) = {lap} mm, không nhỏ hơn {minimum} mm (Bảng 25.5.2.1).",
  'detailing.joint.assumedJd': "Cánh tay đòn nội lực đàn hồi được lấy là jd = {ratio} d. §15.4.1.1 yêu cầu lực kéo và lực nén do uốn sinh ra nhưng không quy định cách xác định jd; đây là giá trị thường dùng cho tiết diện chữ nhật, không phải giá trị theo quy định.",
  'detailing.joint.unsupported.noIncidentBeams': "Không có dầm nào liên kết vào nút này, nên không thể lập sơ đồ vật thể tự do.",
  'detailing.joint.unsupported.biaxial': "Nút có dầm theo cả hai phương trong mặt bằng. Kiểm tra hai phương đòi hỏi thiết lập lực cắt theo từng phương với Aj riêng và tổ hợp các tác động; chức năng này chưa được triển khai. Lực cắt nút CHƯA ĐƯỢC KIỂM TRA.",
  'detailing.joint.unsupported.equilibriumResidual': "Sơ đồ vật thể tự do của nút không khép kín: sai số cân bằng là {residual} % của lực thành phần lớn nhất so với giới hạn {limit} %. Lực cắt nút CHƯA ĐƯỢC KIỂM TRA: kết quả lấy từ sơ đồ vật thể tự do không khép kín không phải là một phép kiểm tra.",
  'detailing.joint.memo.freeBody': "Vật thể tự do ở giữa chiều cao nút (§15.4.1.1): {tensions}, Vcol = {columnShear} kN → Vu = {vu} kN.",
  'detailing.joint.memo.residual': "Sai số cân bằng {residual} % (giới hạn {limit} %).",
  'detailing.joint.memo.effectiveArea': "Aj = {depth} × {width} = {aj} m² (§15.4.2.4, do {governedBy} quyết định).",
  'detailing.joint.memo.nominalShear': "Vn = {coefficient} λ √f′c Aj = {vn} kN; φVn = {phiVn} kN so với Vu = {vu} kN.",
